# ---- the base manifest: voices/joshua/manifest.json from harry's shape (ids, order, when, category) and BASE
def write_base() -> None:
    import json
    from pathlib import Path
    here = Path(__file__).resolve().parent / "stock" / "voices"
    ref = json.loads((here / "harry" / "manifest.json").read_text())
    out = here / "joshua"
    out.mkdir(parents=True, exist_ok=True)
    m = {"schema": "arena.voice-stock/1", "library": "joshua", "seat": 0,
         "voice": "Joshua - W.O.P.R. (Ben's ElevenLabs account), eleven_v3 stability 0.5 speed 0.92",
         "voice_id": "SBbMtfucc8NAkpyzIRvP", "voice_name": "Joshua - W.O.P.R.",
         "temperament": ("the calm machine: measured, dry, precise, faintly amused; never shouts; short declaratives and the "
                         "occasional probability. The advisor's voice, seated at the table only when no human sits at seat 0."),
         "render": {"model": "eleven_v3", "voice_settings": {"stability": 0.5, "speed": 0.92}, "formats": ["pcm_24000"]},
         "bake": dict(ref["bake"]), "sample_rate": ref.get("sample_rate", 22050), "tags_note": ref.get("tags_note", ""),
         "sources": {"joshua-seat-2026-09-16": "seat-bark library 'joshua' — the fourth seat's voice for all-AI tables (Ben, 2026-09-16); "
                                               "wordings in runner/voice/joshua_lines.py"},
         "phrases": {}}
    for pid, ph in ref["phrases"].items():
        m["phrases"][pid] = {k: v for k, v in ph.items() if k in ("when", "category")}
        m["phrases"][pid]["text"] = list(BASE[pid])
        m["phrases"][pid]["source"] = "joshua-seat-2026-09-16"
    try:
        old = json.loads((out / "manifest.json").read_text())
        if old.get("baked"):
            m["baked"] = old["baked"]
    except (OSError, ValueError):
        pass
    (out / "manifest.json").write_text(json.dumps(m, indent=1, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    write_base()
